261	// the music above, the dance below: each block of the chain in its colour, red where it runs past the music
262	function musicBar(id, np, dance, info) {
263	  const N = NUMBERS[id], scale = Math.max(N.counts, info.phrase, 1), W0 = 100;
264	  let blocks = '';
265	  for (const mk of dance.marks.slice(0, 120)) {
