268	    blocks += `<rect x="${x0}" y="9" width="${Math.max(0.2, x1 - x0 - 0.25)}" height="6" rx="1" fill="${s1 > N.counts ? '#ff6f6f' : blockColor(np, mk.block)}"/>`;
269	  }
270	  const mW = (N.counts / scale) * W0;
271	  return `<svg class="musicbar" viewBox="-1 0 102 22" role="img" aria-label="${esc(t().musicBar)}"><text x="0" y="3.6">${esc(t().musicBar)}</text><rect x="0" y="4.5" width="${mW}" height="3.2" rx="1" fill="#f5b942"/><text x="0" y="20.5">${esc(t().yourDance)}</text>${blocks}<line x1="${mW}" x2="${mW}" y1="3" y2="16" stroke="#fff" stroke-width=".3" stroke-dasharray="1 .6"/></svg>`;
