273	function forecastBox(P, cls) {
274	  const s = P.state, meter = (label, v, good) => { const ok = good === 'high' ? v >= 60 : v <= 40, bad = good === 'high' ? v < 40 : v > 60; return `<div class="meter"><span>${esc(label)}</span><span class="bar"><i style="width:${v}%;background:${ok ? 'var(--good)' : bad ? 'var(--bad)' : 'var(--warn)'}"></i></span><b>${v}</b></div>`; };
275	  const reasons = riskReasons(P, cls);
276	  return `<h3>${esc(t().forecastH)}</h3><div class="meters">${meter(t().energy, s.energy, 'high')}${meter(t().hunger, s.hunger, 'low')}${meter(t().nerves, s.nerves, 'low')}${meter(t().focus, s.focus, 'high')}</div>`
277	    + `<p class="risk ${P.risk}">${esc(t().risk[P.risk])}</p>${reasons.length ? `<ul class="facts">${reasons.map((r) => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}`;
278	}
279	function riskReasons(P, cls) {
280	  const S = t().sum, out = [], ex = P.ex;
281	  for (const x of ex.per) if (x.gap >= 1 && !out.some((o) => o.includes(moveName(x.id)))) out.push(S.tooHard(moveName(x.id), MOVES[x.id].d, cls.exp));
282	  if (ex.per.some((x) => x.streak)) out.push(S.streak);
283	  if (ex.bored > 0) out.push(S.bored(num(P.info.avgDiff), cls.exp));
284	  if (ex.long) out.push(S.longRep(P.dance.mostRepeated));
285	  if (ex.shoe > 1) out.push(S.pointes);
286	  if (P.state.energy < 55) out.push(`${t().energy} ${P.state.energy}`);
287	  if (P.state.hunger > 50) out.push(`${t().hunger} ${P.state.hunger}`);
288	  if (P.state.nerves > 50) out.push(`${t().nerves} ${P.state.nerves}`);
289	  if (P.state.focus < 55) out.push(`${t().focus} ${P.state.focus}`);
290	  return out.slice(0, 6);
291	}
