306	    let path = `${p.x},${D - p.z}`, x = p.x, z = p.z, cur = F, other = cur === np.A ? (np.B || np.A) : np.A;
307	    pathMoves.forEach((mid) => { const m = MOVES[mid]; if (m.swap && np.B) { x += other[sel].x - cur[sel].x; z += other[sel].z - cur[sel].z; [cur, other] = [other, cur]; } x += m.dx || 0; z += m.dz || 0; path += ` ${x},${D - z}`; });
308	    s += `<polyline points="${path}" fill="none" stroke="#7cc6ff" stroke-width="0.05" stroke-dasharray="0.15 0.1"/>`;
