310	    s += `<line x1="${p.x - r}" y1="${D - p.z}" x2="${p.x + r}" y2="${D - p.z}" stroke="#f5b942" stroke-width="0.07"/><circle cx="${p.x - r}" cy="${D - p.z}" r="0.08" fill="#f5b942"/><circle cx="${p.x + r}" cy="${D - p.z}" r="0.08" fill="#f5b942"/>`;
311	    s += `<text class="lbl gold" x="${p.x}" y="${D - p.z - r - 0.14}">${esc(t().arms)}</text>`;
