317	    s += `<g id="ruler" transform="translate(${R.x} ${D - R.z}) rotate(${-R.a})"><rect x="-0.08" y="-0.02" width="${L + 0.16}" height="0.42" rx="0.03" fill="#ffe7a8" stroke="#2b2236" stroke-width="0.02" style="cursor:move"/>${ticks}<circle id="rulerTurn" cx="${L + 0.25}" cy="0.2" r="0.16" fill="#f5b942" stroke="#2b2236" stroke-width="0.02" style="cursor:alias"/></g>`;
