412	    if (G.selected) h += `<div class="chips"><button type="button" id="rotSel">${esc(t().rotate)}</button><button type="button" id="movSel">${esc(t().move)}</button><button type="button" id="delSel">${esc(t().remove)} · ${esc(nm(PIECES[G.selected.id]))}</button></div>`;
