415	      return `<button type="button" data-piece="${id}" aria-pressed="${G.armed && G.armed.id === id}" class="${own ? '' : 'locked'}"><span>${p.icon}</span>${esc(nm(p))}<small>${esc(own ? tags : `${t().buy(p.price)} · ${tags}`)}</small></button>`;
416	    }).join('')}</div>`;
417	  }
418	  sbody.innerHTML = h;
419	  const ni = sbody.querySelector('#nameIn'); ni.oninput = () => { sc.name = ni.value.slice(0, 40); save(); W.drawSign(schoolName()); hud(); };
420	  const gd = sbody.querySelector('#goDr'); if (gd) gd.onclick = () => pickRoom('dr');
421	  for (const b of sbody.querySelectorAll('[data-piece]')) b.onclick = () => {
