427	  const rs = sbody.querySelector('#rotSel'); if (rs) rs.onclick = rotateSelected;
428	  const ms = sbody.querySelector('#movSel'); if (ms) ms.onclick = moveSelected;
429	  const ds = sbody.querySelector('#delSel'); if (ds) ds.onclick = removeSelected;
430	}
431	export function rotateArmed() { if (!G.armed) return; G.armed.rot = (G.armed.rot + 1) % 4; if (W.ghost.f) { const f = { ...W.ghost.f, rot: G.armed.rot }; showGhost(f); } }
432	export function rotateSelected() {
433	  const f = G.selected; if (!f) return; const old = { c: f.c, r: f.r, rot: f.rot }, cols = G.S.school.logeCols;
434	  f.rot = (f.rot + 1) % 4;
435	  if (!fits(f, G.S.school.furniture, cols, f)) { const fp = footprint(f); f.c = clamp(f.c, 0, cols - fp.w); f.r = clamp(f.r, 0, LOGE.rows - fp.d); if (!fits(f, G.S.school.furniture, cols, f)) Object.assign(f, old); }
