#cam button { font: 700 13px var(--body); height: 34px; min-width: 34px; padding: 0 10px; background: var(--panel); color: var(--fg); border: 1px solid var(--line); border-radius: 9px; cursor: pointer; white-space: nowrap; }
#cam button[aria-pressed="true"] { border-color: var(--accent); background: rgba(245,185,66,.25); }
#sheet { position: fixed; z-index: 2; background: var(--panel); backdrop-filter: blur(8px); display: flex; flex-direction: column; }
#sheet.side { right: 0; top: 0; bottom: 0; width: 400px; border-left: 1px solid var(--line); padding-top: env(safe-area-inset-top, 0px); }
#sheet.bottom { left: 0; right: 0; bottom: 0; max-height: 56vh; border-top: 1px solid var(--line); border-radius: 16px 16px 0 0; }
@media (max-width: 760px) { #top { max-width: 100vw; } }
.tabs { display: flex; flex-wrap: wrap; gap: 3px; padding: 10px 10px 6px; }
.tabs button { font: 600 14px var(--display); color: var(--muted); background: transparent; border: 0; border-radius: 8px; padding: 6px 8px; cursor: pointer; }
.tabs button[aria-selected="true"] { color: var(--accent-ink); background: var(--accent); }
#sbody { flex: 1; overflow-y: auto; padding: 4px 16px 12px; min-height: 0; touch-action: pan-y; }
#sbody h2 { font: 600 19px var(--display); margin: 6px 0 6px; text-wrap: balance; }
#sbody h3 { font: 600 15px var(--display); margin: 14px 0 4px; color: var(--accent); }
.sub { margin: 8px 0 2px; font-weight: 800; display: flex; align-items: center; gap: 6px; }
.facts { margin: 4px 0 10px; padding: 0; list-style: none; display: grid; gap: 3px; }
.facts li { font-size: 14px; color: var(--muted); padding-left: 14px; position: relative; line-height: 1.35; }
.facts li::before { content: "•"; position: absolute; left: 2px; color: var(--accent); }
.facts b { color: var(--fg); }
.go { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 10px 12px calc(env(safe-area-inset-bottom, 0px) + 12px); border-top: 1px solid var(--line); }
.go button { font: 600 15px var(--display); border-radius: 12px; padding: 11px 8px; cursor: pointer; border: 2px solid var(--accent); }
.go .reh { background: transparent; color: var(--fg); }
.go .reh[aria-pressed="true"] { background: rgba(245,185,66,.18); }
.go .gala { background: var(--velvet); border-color: var(--velvet); color: #fff; }
.go button:disabled { opacity: .5; cursor: default; }
.go .wide { grid-column: 1 / -1; }
.step { display: flex; align-items: center; gap: 8px; margin: 6px 0; }
.step .lab { flex: 1; font-weight: 700; }
.step button { width: 34px; height: 34px; border-radius: 9px; border: 1px solid var(--line); background: var(--panel2); color: var(--fg); font: 800 18px var(--body); cursor: pointer; }
.step output { min-width: 92px; text-align: center; font: 600 17px var(--display); font-variant-numeric: tabular-nums; background: rgba(0,0,0,.25); border-radius: 8px; padding: 5px 6px; }
.cards { display: grid; gap: 6px; margin: 6px 0; }
.card { display: flex; align-items: center; gap: 8px; background: var(--panel2); border: 1px solid var(--line); border-radius: 10px; padding: 7px 8px; cursor: grab; touch-action: none; }
.card.locked { cursor: default; opacity: .85; }
.card.dragging { border-color: var(--accent); background: rgba(245,185,66,.18); }
.dot { width: 10px; height: 10px; border-radius: 50%; flex: none; display: inline-block; }
.card .nm { flex: 1; font-weight: 700; min-width: 0; }
.card .du { font: 600 14px var(--display); font-variant-numeric: tabular-nums; color: var(--muted); white-space: nowrap; }
.card .tags { white-space: nowrap; }

