    const x0 = (s0 / scale) * 100, x1 = Math.min((s1 / scale) * 100, 100);
    segs.push({ id: `m${mk.j}`, left: x0, width: Math.max(0.2, x1 - x0 - 0.25), color: s1 > N.counts ? '#ff6f6f' : blockColor(np, mk.block) });
  }

