    plan: { width: PLAN_W, height: g.h, k: g.k, W: g.W, D: g.D, stageLeft: g.px(-g.W), stageTop: g.py(g.D), stageWidth: 2 * g.W * g.k, stageHeight: g.D * g.k, wing: 0.9 * g.k },
