    if (PIECES[f.id].wall && !againstWall(f, cols)) { const r = new T.Mesh(new T.RingGeometry(0.35, 0.48, 24), badRingMat); r.rotation.x = -Math.PI / 2; r.position.set(g.position.x, 0.07, g.position.z); furnG.add(r); }
  }
  const s = G.selected;
  if (s && G.S.school.furniture.includes(s)) { const fp = footprint(s); selRing.visible = true; selRing.position.set(ROOMS.dr.x0 + s.c + fp.w / 2, 0.06, ROOMS.dr.z0 + s.r + fp.d / 2); selRing.scale.setScalar(Math.max(fp.
}
export function spinFans(dt) { furnG.traverse((o) => { if (o.userData.spin) o.rotation.z += dt * 12; }); }
export const ghost = { g: null, f: null };
